from admissions_records import *
def s(url,en,ru):return S(url,L(en,ru),access='web-html-read')
system='https://admission.universityofcalifornia.edu/admission-requirements/international-applicants/english-language-proficiency-toefl-ielts.html'
academic='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-first-year/filling-out-the-application.html'
for uid,campus,url in [('university-of-california-davis','Davis','https://www.ucdavis.edu/admissions/undergraduate/international/exams-visas'),('university-of-california-irvine','Irvine','https://www.admissions.uci.edu/apply/international-students.php'),('university-of-california-merced','Merced','https://admissions.ucmerced.edu/international/english-language-proficiency')]:
 e={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic; One Skill Retake not accepted','min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':80},{'period':'post2026','min':4.5}]},'alternatives':L('UC first-year baseline: Duolingo 115, specified AP/IB English, legacy ACT/SAT or qualifying English composition. School language history determines the requirement, not citizenship. MyBest and digital SAT English substitution are not approved by the system page.','Базовое правило UC первокурсников: Duolingo 115, указанные AP/IB English, прежние ACT/SAT либо подходящий English composition. Требование зависит от языка школы, не гражданства. Системная страница не одобряет MyBest и замену английского digital SAT.')}
 if campus=='Irvine':e['note']=L('Irvine also lists SAT EBRW 680 for English, while the UC system page says digital SAT Reading/Writing is not approved. The version is unresolved; a digital SAT score is not counted as a verified waiver.','Irvine также указывает SAT EBRW 680 для английского, тогда как система UC не одобряет digital SAT Reading/Writing. Версия не прояснена; digital SAT не считается подтверждённым освобождением.')
 if campus=='Merced':e['note']=L('Merced still lists legacy TOEFL 80 without the new-scale row; the system publishes 4.5. Mixed-school records have separately named legacy exam alternatives. An undated January score-receipt rule is not assigned a Fall 2027 calendar date.','Merced ещё указывает прежний TOEFL 80 без новой строки; система публикует 4,5. Для смешанной школьной истории отдельно названы прежние экзамены. Правилу получения результатов в январе без года не назначается дата календаря Fall 2027.')
 record(uid,[route(label=L('UC '+campus+' international first-year entry','UC '+campus+': международный приём первокурсников'),english=e,academic={'satPolicy':'not-used','note':L('UC does not consider SAT/ACT in admission selection or scholarship awards. Limited eligibility-subject and post-enrolment placement uses are separate.','UC не учитывает SAT/ACT в отборе на поступление и стипендии. Ограниченное подтверждение учебных предметов и распределение после зачисления — отдельные основания.')},sources=[s(url,'UC '+campus+' first-year English context','UC '+campus+': английский первокурсников'),s(system,'UC system first-year English benchmarks — not UCEAP exchange','Система UC: языковые условия первокурсника, не обмен UCEAP'),s(academic,'UC first-year SAT/ACT selection policy','UC: политика SAT/ACT отбора первокурсников')])],'Replaced exchange-route evidence with first-year campus/system sources and separated English proof from test-blind academic selection.', ['Fall 2027-labelled confirmation, IELTS sections and individual school-language/qualification assessment remain unconfirmed.'])

u='https://www.rockhurst.edu/admissions/international'
record('rockhurst-university',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':80}]},'alternatives':L('PTE 54; DET 110; SAT Reading/Writing 550; ACT English 21; qualifying non-ESL US college English. These are language alternatives, not additional mandatory academic SAT scores.','PTE 54; DET 110; SAT Reading/Writing 550; ACT English 21; подходящий не-ESL английский колледжа США. Это языковые альтернативы, а не дополнительно обязательный академический SAT.'),'waiver':L('Listed citizenship categories or the entire high-school curriculum in English may qualify. School-history evidence must come directly from a school official, not the applicant.','Могут подойти перечисленные категории гражданства либо вся школьная программа на английском. Подтверждение истории школы должен направить её представитель, а не кандидат.')},academic={'satPolicy':'optional','note':L('All undergraduate programmes use optional SAT/ACT according to the freshman page. English proof remains independent.','По странице первокурсников во всех бакалаврских программах SAT/ACT необязательны. Языковое подтверждение сохраняется отдельно.')},sources=[s(u,'Rockhurst international language proof and waiver categories','Rockhurst: международное языковое подтверждение и освобождения'),s('https://www.rockhurst.edu/freshman','Rockhurst freshman test-optional policy','Rockhurst: test-optional политика первокурсников')])],'Separated optional academic tests from their accepted English subscores and documented school-official waiver evidence.', ['Fall 2027-labelled policy, new TOEFL scale, IELTS sections and exact test variants remain unconfirmed.'])

u='https://salve.edu/admissions/first-year-applicants'
ep='https://salve.edu/our-mission/campus-offices-and-services/center-global-education-and-fellowships/international-student-support/english-academic-purposes'
aa={'satPolicy':'optional','note':L('SAT/ACT optional for all applicants, including Nursing; Nursing encourages scores but its admitted-student averages are not requirements.','SAT/ACT необязательны для всех кандидатов, включая Nursing; Nursing рекомендует баллы, но средние зачисленных не являются требованиями.')}
record('salve-regina-university',[route(id='general-first-year',english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None},'toefl':{'accepted':True},'alternatives':L('TOEFL, IELTS or Duolingo results required when English is not the first language. The first-year checklist does not publish an unconditional numerical minimum.','Когда английский не родной, нужны результаты TOEFL, IELTS либо Duolingo. Список первокурсника не публикует числовой безусловный минимум.')},academic=aa,sources=[s(u,'Salve first-year checklist and optional academic testing','Salve: список первокурсника и необязательные академические тесты')]),route(id='eap-degree',kind='degree-with-esl',label=L('Full bachelor admission with required English for Academic Purposes','Полный бакалаврский приём с обязательным English for Academic Purposes'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6,'role':'admission'},'alternatives':L('Published EAP category: TOEFL iBT 60–79, IELTS 6.0, DET 90–105 or PTE 46–52. Four required credit-bearing EAP courses accompany degree courses over two semesters. This is full degree admission with language support, not a standalone Foundation.','Опубликованная категория EAP: TOEFL iBT 60–79, IELTS 6,0, DET 90–105 либо PTE 46–52. Четыре обязательных кредитных курса EAP идут вместе с предметами степени два семестра. Это полный приём на степень с языковой поддержкой, а не отдельный Foundation.')},academic=aa,sources=[s(ep,'Salve EAP full-degree route, eligibility and progression','Salve EAP: маршрут полной степени, допуск и продолжение')])],'Made full degree admission with EAP distinct from unassisted English readiness; no invented regular IELTS cutoff.', ['Fall 2027-specific applicability, EAP test variants/section rules, waiver categories and the unconditional language minimum require confirmation.'])
finish()
